    ('R35_shell_test_or_check_skips_it', 'unknown', 'quiet', 'pipeline {\n  agent any\n  parameters { booleanParam(name: \'SKIP_VERIFY\', defaultValue: false) }\n  environment { SKIP_VERIFY = "${params.SKIP_VERIFY}" }\n  stages {\n    stage(\'Verify\') { steps { sh \'[ "$SKIP_VERIFY" = "true" ] || obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz\' } }\n    stage(\'Publish\') { steps { sh \'docker push registry.example.com/app:1.0\' } }\n  }\n}\n'),
    ('R36_shell_if_file_exists_check', 'unknown', 'quiet', "pipeline {\n  agent any\n  stages {\n    stage('Verify') {\n      steps {\n        sh '''if [ -f release-policy.json ]; then\n  obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz\nfi\n'''\n      }\n    }\n    stage('Publish') { steps { sh 'docker push registry.example.com/app:1.0' } }\n  }\n}\n"),
    ('R37_check_cmd_in_variable_or_true', 'quiet', 'quiet', "def VERIFY = 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz || true'\n\npipeline {\n  agent any\n  stages {\n    stage('Verify') { steps { sh VERIFY } }\n    stage('Publish') { steps { sh 'docker push registry.example.com/app:1.0' } }\n  }\n}\n"),
    ('S01_catchError_check_then_publish_same_block', 'quiet', 'finding-high', "pipeline {\n  agent any\n  stages {\n    stage('Release') {\n      steps {\n        catchError(buildResult: 'UNSTABLE', stageResult: 'FAILURE') {\n          sh 'sha256sum -c SHA256SUMS'\n          sh 'twine upload dist/*'\n        }\n      }\n    }\n  }\n}\n"),
    ('S02_try_check_publish_catch_notify', 'quiet', 'finding-high', 'node {\n  try {\n    sh \'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz\'\n    sh \'docker push registry.example.com/app:1.0\'\n  } catch (err) {\n    echo "release failed: ${err}"\n  }\n}\n'),
    ('S03_warnError_check_then_publish_same_block', 'quiet', 'finding-high', "node {\n  warnError('release failed') {\n    sh 'cosign verify --key cosign.pub registry.example.com/app:1.0'\n    sh 'docker push registry.example.com/app:1.0'\n  }\n}\n"),
    ('S04_nested_catchError_publish_inner', 'finding-high', 'finding-high', "node {\n  catchError {\n    sh 'sha256sum -c SHA256SUMS'\n    catchError(buildResult: 'UNSTABLE') {\n      sh 'twine upload dist/*'\n    }\n  }\n}\n"),
    ('S05_check_earlier_stage_publish_later', 'quiet', 'quiet', "pipeline {\n  agent any\n  stages {\n    stage('Build') { steps { sh 'make dist' } }\n    stage('Verify') { steps { sh 'sha256sum -c SHA256SUMS'; sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz' } }\n    stage('Publish') { steps { sh 'docker push registry.example.com/app:1.0' } }\n  }\n}\n"),
    ('S06_check_then_post_success_publish', 'quiet', 'quiet', "pipeline {\n  agent any\n  stages {\n    stage('Verify') { steps { sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz' } }\n  }\n  post { success { sh 'docker push registry.example.com/app:1.0' } }\n}\n"),
    ('S07_check_earlier_stage_publish_in_stage_post_success', 'quiet', 'quiet', "pipeline {\n  agent any\n  stages {\n    stage('Verify') { steps { sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz' } }\n    stage('Package') {\n      steps { sh 'make package' }\n      post { success { sh 'docker push registry.example.com/app:1.0' } }\n    }\n  }\n}\n"),
    ('S08_scripted_stages', 'quiet', 'quiet', "node {\n  stage('Build') { sh 'make dist' }\n  stage('Verify') { sh 'sha256sum -c SHA256SUMS' }\n  stage('Publish') { sh 'twine upload dist/*' }\n}\n"),
    ('S09_matrix_cell_check_then_publish', 'quiet', 'quiet', "pipeline {\n  agent any\n  stages {\n    stage('Matrix') {\n      matrix {\n        axes { axis { name 'ARCH'; values 'amd64', 'arm64' } }\n        stages {\n          stage('Verify') { steps { sh 'cosign verify --key cosign.pub registry.example.com/app:1.0-${ARCH}' } }\n          stage('Publish') { steps { sh 'docker push registry.example.com/app:1.0-${ARCH}' } }\n        }\n      }\n    }\n  }\n}\n"),
    ('S10_parallel_checks_then_publish', 'quiet', 'quiet', "node {\n  parallel(\n    sums: { sh 'sha256sum -c SHA256SUMS' },\n    provenance: { sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz' }\n  )\n  sh 'docker push registry.example.com/app:1.0'\n}\n"),
    ('S11_swallowed_precheck_then_strict_same_check', 'finding-high', 'finding-high', "pipeline {\n  agent any\n  stages {\n    stage('Report') { steps { sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz || true' } }\n    stage('Verify') { steps { sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz' } }\n    stage('Publish') { steps { sh 'docker push registry.example.com/app:1.0' } }\n  }\n}\n"),
    ('S12_check_after_publish_swallowed', 'quiet', 'quiet', "node {\n  sh 'docker push registry.example.com/app:1.0'\n  sh 'cosign verify --key cosign.pub registry.example.com/app:1.0 || true'\n}\n"),
    ('S13_declarative_parallel_checks_then_publish_stage', 'quiet', 'quiet', "pipeline {\n  agent any\n  stages {\n    stage('Checks') {\n      parallel {\n        stage('Sums') { steps { sh 'sha256sum -c SHA256SUMS' } }\n        stage('Provenance') { steps { sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz' } }\n      }\n    }\n    stage('Publish') { steps { sh 'docker push registry.example.com/app:1.0' } }\n  }\n}\n"),
    ('X01_declarative_parallel_failfast', 'finding-high', 'finding-high', "pipeline {\n  agent any\n  stages {\n    stage('Release') {\n      failFast true\n      parallel {\n        stage('Verify') { steps { sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz' } }\n        stage('Publish') { steps { sh 'docker push registry.example.com/app:1.0' } }\n      }\n    }\n  }\n}\n"),
    ('X02_scripted_parallel_map', 'finding-high', 'finding-high', "node {\n  parallel(\n    verify: { sh 'sha256sum -c SHA256SUMS' },\n    publish: { sh 'twine upload dist/*' }\n  )\n}\n"),
    ('X03_scripted_parallel_closure_var_by_name', 'unknown', 'quiet', "def verify = {\n  sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz'\n}\n\nnode {\n  parallel(verify: verify, publish: { sh 'docker push registry.example.com/app:1.0' })\n}\n"),
    ('X04_parallel_built_map', 'finding-high', 'finding-high', "node {\n  def branches = [:]\n  branches['verify'] = { sh 'sha256sum -c SHA256SUMS' }\n  branches['publish'] = { sh 'twine upload dist/*' }\n  parallel branches\n}\n"),
    ('X05_when_on_check_only', 'finding-high', 'finding-high', "pipeline {\n  agent any\n  stages {\n    stage('Verify') {\n      when { branch 'main' }\n      steps { sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz' }\n    }\n    stage('Publish') { steps { sh 'docker push registry.example.com/app:1.0' } }\n  }\n}\n"),
    ('X06_when_same_on_both', 'quiet', 'quiet', "pipeline {\n  agent any\n  stages {\n    stage('Verify') {\n      when { branch 'main' }\n      steps { sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz' }\n    }\n    stage('Publish') {\n      when { branch 'main' }\n      steps { sh 'docker push registry.example.com/app:1.0' }\n    }\n  }\n}\n"),
    ('X07_when_publish_condition_implies_check', 'finding-high', 'finding-high', "pipeline {\n  agent any\n  parameters { booleanParam(name: 'RELEASE', defaultValue: false) }\n  stages {\n    stage('Verify') {\n      when { branch 'main' }\n      steps { sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz' }\n    }\n    stage('Publish') {\n      when { allOf { branch 'main'; expression { params.RELEASE } } }\n      steps { sh 'docker push registry.example.com/app:1.0' }\n    }\n  }\n}\n"),
    ('X08_when_expression_return_vs_plain', 'finding-high', 'finding-high', "pipeline {\n  agent any\n  parameters { booleanParam(name: 'RELEASE', defaultValue: false) }\n  stages {\n    stage('Verify') {\n      when { expression { return params.RELEASE } }\n      steps { sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz' }\n    }\n    stage('Publish') {\n      when { expression { params.RELEASE } }\n      steps { sh 'docker push registry.example.com/app:1.0' }\n    }\n  }\n}\n"),
    ('X09_if_check_else_error', 'finding-high', 'finding-high', "node {\n  stage('Verify') {\n    if (fileExists('SHA256SUMS')) {\n      sh 'sha256sum -c SHA256SUMS'\n    } else {\n      error 'SHA256SUMS is missing'\n    }\n  }\n  stage('Publish') { sh 'twine upload dist/*' }\n}\n"),
    ('X10_script_conditional_return_skips_check', 'quiet', 'quiet', "pipeline {\n  agent any\n  parameters { booleanParam(name: 'SKIP_VERIFY', defaultValue: false) }\n  stages {\n    stage('Verify') {\n      steps {\n        script {\n          if (params.SKIP_VERIFY) {\n            echo 'skipping verification'\n            return\n          }\n          sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz'\n        }\n      }\n    }\n    stage('Publish') { steps { sh 'docker push registry.example.com/app:1.0' } }\n  }\n}\n"),
    ('X11_switch_case_check', 'finding-high', 'finding-high', "node {\n  switch (params.MODE) {\n    case 'strict':\n      sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz'\n      break\n    default:\n      echo 'no verification'\n  }\n  sh 'docker push registry.example.com/app:1.0'\n}\n"),
    ('X12_when_differs_branch_vs_tag', 'finding-high', 'finding-high', "pipeline {\n  agent any\n  stages {\n    stage('Verify') {\n      when { branch 'main' }\n      steps { sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz' }\n    }\n    stage('Publish') {\n      when { buildingTag() }\n      steps { sh 'docker push registry.example.com/app:1.0' }\n    }\n  }\n}\n"),
    ('X13_if_params_around_both', 'quiet', 'quiet', "node {\n  if (params.RELEASE) {\n    sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz'\n    sh 'docker push registry.example.com/app:1.0'\n  }\n}\n"),
    ('X14_each_literal_list_check', 'finding-high', 'finding-high', 'node {\n  [\'app.tar.gz\', \'app.zip\'].each { f ->\n    sh "sha256sum -c dist/${f}.sha256"\n  }\n  sh \'twine upload dist/*\'\n}\n'),
    ('X15_parent_when_guards_both_child_stages', 'quiet', 'quiet', "pipeline {\n  agent any\n  stages {\n    stage('Release') {\n      when { buildingTag() }\n      stages {\n        stage('Verify') { steps { sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz' } }\n        stage('Publish') { steps { sh 'docker push registry.example.com/app:1.0' } }\n      }\n    }\n  }\n}\n"),
    ('X16_parallel_per_platform_verify_then_upload', 'finding-high', 'finding-high', "pipeline {\n  agent any\n  stages {\n    stage('Release') {\n      parallel {\n        stage('linux') {\n          steps {\n            sh 'sha256sum -c dist/linux.sha256'\n            sh 'aws s3 cp dist/app-linux.tar.gz s3://releases/'\n          }\n        }\n        stage('windows') {\n          steps {\n            sh 'sha256sum -c dist/windows.sha256'\n            sh 'aws s3 cp dist/app-windows.zip s3://releases/'\n          }\n        }\n      }\n    }\n  }\n}\n"),
    ('M01_method_check_called_before', 'quiet', 'quiet', "def verifyRelease() {\n  sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz'\n}\n\nnode {\n  verifyRelease()\n  sh 'docker push registry.example.com/app:1.0'\n}\n"),
    ('M02_method_check_swallowed_called_before', 'finding-high', 'quiet', 'def verifySums() {\n  sh \'sha256sum -c SHA256SUMS || echo "mismatch"\'\n}\n\nnode {\n  verifySums()\n  sh \'twine upload dist/*\'\n}\n'),
    ('M03_helper_runs_body_in_catchError', 'finding-high', 'finding-high', "def soft(Closure body) {\n  catchError(buildResult: 'UNSTABLE', stageResult: 'UNSTABLE') {\n    body()\n  }\n}\n\nnode {\n  soft {\n    sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz'\n  }\n  sh 'docker push registry.example.com/app:1.0'\n}\n"),
    ('M04_helper_lock_body', 'quiet', 'quiet', "def withReleaseLock(Closure body) {\n  lock('release') {\n    body()\n  }\n}\n\nnode {\n  withReleaseLock {\n    sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz'\n  }\n  sh 'docker push registry.example.com/app:1.0'\n}\n"),
    ('M05_check_in_uncalled_closure', 'unknown', 'quiet', "def verify = {\n  sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz'\n}\n\npipeline {\n  agent any\n  stages {\n    stage('Publish') { steps { sh 'docker push registry.example.com/app:1.0' } }\n  }\n}\n"),
    ('M06_check_in_uncalled_method', 'unknown', 'quiet', "def verifySums() {\n  sh 'sha256sum -c SHA256SUMS'\n}\n\nnode {\n  stage('Publish') { sh 'twine upload dist/*' }\n}\n"),
    ('M07_swallowed_check_closure_called_after_publish', 'quiet', 'finding-high', "def softVerify = {\n  sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz || true'\n}\n\nnode {\n  sh 'docker push registry.example.com/app:1.0'\n  softVerify()\n}\n"),
    ('M08_check_closure_via_method_pointer_parallel', 'unknown', 'quiet', "def verifyRelease() {\n  sh 'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz'\n}\n\nnode {\n  parallel(verify: this.&verifyRelease, publish: { sh 'docker push registry.example.com/app:1.0' })\n}\n"),
    ('M09_closure_check_called_before', 'quiet', 'quiet', "def verify = {\n  sh 'sha256sum -c SHA256SUMS'\n}\n\nnode {\n  verify()\n  sh 'twine upload dist/*'\n}\n"),
    ('M10_method_try_catch_around_body', 'finding-high', 'finding-high', 'def tolerant(String what, Closure body) {\n  try {\n    body()\n  } catch (err) {\n    echo "${what} failed: ${err}"\n  }\n}\n\nnode {\n  tolerant(\'verify\') {\n    sh \'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz\'\n  }\n  sh \'docker push registry.example.com/app:1.0\'\n}\n'),
    ('D01_realworld_python_release', 'finding-high', 'quiet', 'pipeline {\n  agent { docker { image \'python:3.12\' } }\n  environment { TWINE_NON_INTERACTIVE = \'1\' }\n  stages {\n    stage(\'Build\') {\n      steps {\n        sh \'python -m pip install build twine\'\n        sh \'python -m build\'\n      }\n    }\n    stage(\'Verify\') {\n      steps {\n        sh \'\'\'cd dist\nsha256sum -c ../SHA256SUMS || echo "WARNING: checksum mismatch"\ncd ..\n\'\'\'\n      }\n    }\n    stage(\'Publish\') {\n      when { buildingTag() }\n      steps {\n        withCredentials([string(credentialsId: \'pypi-token\', variable: \'TWINE_PASSWORD\')]) {\n          sh \'TWINE_USERNAME=__token__ twine upload dist/*\'\n        }\n      }\n    }\n  }\n  post {\n    always { archiveArtifacts artifacts: \'dist/*\', fingerprint: true }\n  }\n}\n'),
    ('D02_realworld_container_cosign', 'quiet', 'quiet', "pipeline {\n  agent any\n  environment { IMAGE = 'registry.example.com/team/app' }\n  stages {\n    stage('Build') { steps { sh 'docker build -t $IMAGE:$GIT_COMMIT .' } }\n    stage('Sign') {\n      steps {\n        withCredentials([file(credentialsId: 'cosign-key', variable: 'COSIGN_KEY')]) {\n          sh 'cosign sign --key $COSIGN_KEY $IMAGE:$GIT_COMMIT'\n        }\n      }\n    }\n    stage('Verify') { steps { sh 'cosign verify --key cosign.pub $IMAGE:$GIT_COMMIT' } }\n    stage('Push') {\n      when { branch 'main' }\n      steps { sh 'docker push $IMAGE:$GIT_COMMIT' }\n    }\n  }\n}\n"),
    ('D03_realworld_scripted_finally_upload', 'finding-high', 'finding-high', "node('linux') {\n  checkout scm\n  try {\n    stage('Build') { sh './gradlew assemble' }\n    stage('Verify') { sh 'slsa-verifier verify-artifact build/libs/app.jar --provenance-path app.intoto.jsonl --source-uri github.com/acme/app' }\n  } finally {\n    stage('Upload') {\n      sh 'aws s3 cp build/libs/app.jar s3://acme-releases/app/'\n    }\n    junit 'build/test-results/**/*.xml'\n  }\n}\n"),
    ('D04_realworld_check_tee_log_then_deploy', 'finding-high', 'finding-high', "pipeline {\n  agent any\n  stages {\n    stage('Verify provenance') {\n      steps {\n        sh 'gh attestation verify dist/app.tar.gz --owner acme 2>&1 | tee attestation.log'\n      }\n    }\n    stage('Deploy') {\n      steps { sh 'gh release upload v1.0 dist/app.tar.gz' }\n    }\n  }\n}\n"),
    ('D05_realworld_soft_gate_param', 'finding-high', 'finding-high', 'pipeline {\n  agent any\n  parameters { booleanParam(name: \'ENFORCE\', defaultValue: true) }\n  stages {\n    stage(\'Verify\') {\n      steps {\n        script {\n          if (params.ENFORCE) {\n            sh \'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz\'\n          } else {\n            sh \'obaaf verify release --policy release-policy.json --artifacts dist/app.tar.gz || echo "not enforced"\'\n          }\n        }\n      }\n    }\n    stage(\'Publish\') { steps { sh \'docker push registry.example.com/app:1.0\' } }\n  }\n}\n'),
    ('D06_realworld_maven_post_failure_snapshot', 'finding-high', 'finding-high', "pipeline {\n  agent any\n  tools { maven 'maven-3.9' }\n  stages {\n    stage('Build') { steps { sh 'mvn -B package' } }\n    stage('Verify') { steps { sh 'sha256sum -c target/checksums.sha256' } }\n  }\n  post {\n    failure {\n      sh 'mvn -B deploy -DaltDeploymentRepository=snapshots::default::https://nexus.example.com/repository/snapshots'\n    }\n  }\n}\n"),
    ('D07_realworld_slsa_bash_shebang_script', 'finding-high', 'finding-high', 'pipeline {\n  agent any\n  stages {\n    stage(\'Verify\') {\n      steps {\n        sh \'\'\'#!/usr/bin/env bash\nslsa-verifier verify-artifact dist/app.tar.gz --provenance-path dist/app.intoto.jsonl --source-uri github.com/acme/app\necho "provenance checked"\n\'\'\'\n      }\n    }\n    stage(\'Release\') { steps { sh \'gh release upload v1.0 dist/app.tar.gz\' } }\n  }\n}\n'),
