    ('V2G04_cd_and_sha_stops', 'unknown', 'quiet', "node {\n  sh '''cd dist && sha256sum -c SUMS'''\n  sh 'twine upload dist/*'\n}\n"),
    ('V2G05_make_and_cosign_pipe_tee', 'finding-high', 'quiet', "node {\n  sh '''make sign && cosign verify --key cosign.pub registry.example.com/app:1.0 | tee v.log'''\n  sh 'docker push registry.example.com/app:1.0'\n}\n"),
    ('V2O01_catchError_or_true_post_success', 'finding-high', 'finding-high', "pipeline {\n  agent any\n  stages {\n    stage('V') { steps { catchError { sh 'obaaf verify release --policy p.json --artifacts dist/a.tgz || true' } } }\n  }\n  post { success { sh 'docker push registry.example.com/app:1.0' } }\n}\n"),
    ('V2O02_try_returnStatus_result_guard', 'finding-high', 'finding-high', "node {\n  try { sh(script: 'cosign verify --key cosign.pub registry.example.com/app:1.0', returnStatus: true) } catch (e) { echo 'x' }\n  if (currentBuild.result == null) { sh 'docker push registry.example.com/app:1.0' }\n}\n"),
    ('V2O03_warnError_background_post_success', 'finding-high', 'finding-high', "pipeline {\n  agent any\n  stages {\n    stage('V') { steps { warnError('v') { sh 'sha256sum -c SUMS &' } } }\n  }\n  post { success { sh 'twine upload dist/*' } }\n}\n"),
    ('V2M01_set_plus_o_errexit_or_true', 'finding-high', 'finding-high', "node {\n  sh '''set +o errexit\nobaaf verify release --policy p.json --artifacts dist/a.tgz || true'''\n  sh 'twine upload dist/*'\n}\n"),
    ('V2M02_set_plus_ex_or_true', 'finding-high', 'finding-high', "node {\n  sh '''set +ex\nobaaf verify release --policy p.json --artifacts dist/a.tgz || true'''\n  sh 'twine upload dist/*'\n}\n"),
    ('V2M03_set_plus_e_then_minus_e_or_true', 'finding-high', 'finding-high', "node {\n  sh '''set +e\nmake clean\nset -e\nobaaf verify release --policy p.json --artifacts dist/a.tgz || true'''\n  sh 'twine upload dist/*'\n}\n"),
    ('V2M04_gh_pipe_then_obaaf_or_true', 'finding-high', 'finding-high', "node {\n  sh '''gh attestation verify dist/a.tgz --owner o | tee att.log\nobaaf verify release --policy p.json --artifacts dist/a.tgz || true'''\n  sh 'twine upload dist/*'\n}\n"),
    ('V2S01_bg_then_pid_wait_pid', 'unknown', 'quiet', "node {\n  sh '''cosign verify --key cosign.pub registry.example.com/app:1.0 &\npid=$!\nmake docs\nwait $pid'''\n  sh 'docker push registry.example.com/app:1.0'\n}\n"),
    ('V2S02_multiline_echo_holds_check_text', 'unknown', 'quiet', 'node {\n  sh \'\'\'echo "To verify by hand:\n  cosign verify --key cosign.pub registry.example.com/app:1.0 || true\nthen push."\'\'\'\n  sh \'docker push registry.example.com/app:1.0\'\n}\n'),
    ('V2S03_uncalled_function_or_true', 'unknown', 'quiet', "node {\n  sh '''soft_verify() { cosign verify --key cosign.pub registry.example.com/app:1.0 || true; }\ncosign verify --key cosign.pub registry.example.com/app:1.0'''\n  sh 'docker push registry.example.com/app:1.0'\n}\n"),
    ('V2S04_group_redirect_under_bash', 'unknown', 'quiet', "node {\n  sh '''#!/bin/bash\n{\n  sha256sum -c SUMS\n} > check.log 2>&1'''\n  sh 'twine upload dist/*'\n}\n"),
    ('V2S05_set_plus_e_check_then_bare_exit', 'unknown', 'quiet', "node {\n  sh '''set +e\nsha256sum -c SUMS\nexit'''\n  sh 'twine upload dist/*'\n}\n"),
    ('V2S06_set_o_errexit_o_pipefail_pipe', 'quiet', 'quiet', "node {\n  sh '''set -o errexit -o pipefail\ncosign verify --key cosign.pub registry.example.com/app:1.0 | tee v.log'''\n  sh 'docker push registry.example.com/app:1.0'\n}\n"),
    ('V2S07_trap_dashdash_exit0_EXIT', 'finding-high', 'quiet', "node {\n  sh '''trap -- 'exit 0' EXIT\nsha256sum -c SUMS'''\n  sh 'twine upload dist/*'\n}\n"),
    ('V2S09_bg_then_bare_wait', 'finding-high', 'quiet', "node {\n  sh '''cosign verify --key cosign.pub registry.example.com/app:1.0 &\nwait'''\n  sh 'docker push registry.example.com/app:1.0'\n}\n"),
    ('V2S10_or_true_then_heredoc_after', 'finding-high', 'quiet', "node {\n  sh '''cosign verify --key cosign.pub registry.example.com/app:1.0 || true\ncat <<EOF\nok\nEOF'''\n  sh 'docker push registry.example.com/app:1.0'\n}\n"),
    ('V2S12_set_plus_e_inside_multiline_string', 'unknown', 'quiet', 'node {\n  sh \'\'\'echo "Tip: to debug, run\nset +e\nin your shell"\nsha256sum -c SUMS\necho ok\'\'\'\n  sh \'twine upload dist/*\'\n}\n'),
    ('V2S14_bash_if_body_check_more', 'unknown', 'quiet', 'node {\n  sh \'\'\'#!/bin/bash\nif [ -n "$CHECK" ]; then\n  sha256sum -c SUMS\nfi\necho done\'\'\'\n  sh \'twine upload dist/*\'\n}\n'),
    ('V2S15_sh_shebang_check_then_comments', 'quiet', 'quiet', "node {\n  sh '''#!/bin/sh\nsha256sum -c SUMS\n# done\n'''\n  sh 'twine upload dist/*'\n}\n"),
    ('V2S16_set_plus_e_check_set_minus_e_more', 'finding-high', 'quiet', "node {\n  sh '''set +e\nsha256sum -c SUMS\nset -e\necho ok'''\n  sh 'twine upload dist/*'\n}\n"),
    ('V2S17_pipe_then_unrelated_dollar_q', 'unknown', 'quiet', 'node {\n  sh \'\'\'cosign verify --key cosign.pub registry.example.com/app:1.0 | tee v.log\nmake report || echo "report failed: $?"\'\'\'\n  sh \'docker push registry.example.com/app:1.0\'\n}\n'),
    ('V2B01_bat_check_then_bare_exit_b', 'unknown', 'quiet', "node {\n  bat '''cosign verify --key cosign.pub registry.example.com/app:1.0\nexit /b'''\n  bat 'docker push registry.example.com/app:1.0'\n}\n"),
    ('V2B02_bat_cosign_exe_more_lines', 'finding-high', 'quiet', "node {\n  bat '''cosign.exe verify --key k.pub img\necho done'''\n  bat 'docker push registry.example.com/app:1.0'\n}\n"),
    ('V2B03_bat_or_exit_b_last_line', 'unknown', 'quiet', "node {\n  bat '''@echo off\ncosign verify --key cosign.pub registry.example.com/app:1.0 || exit /b 1'''\n  bat 'docker push registry.example.com/app:1.0'\n}\n"),
    ('V2X01_python_subprocess_call_list', 'unknown', 'quiet', 'node {\n  sh \'\'\'#!/usr/bin/env python3\nimport subprocess\nsubprocess.call(["cosign", "verify", "--key", "k.pub", "img"])\n\'\'\'\n  sh \'docker push registry.example.com/app:1.0\'\n}\n'),
    ('V2X02_powershell_cosign_exe', 'unknown', 'quiet', "node {\n  powershell '''cosign.exe verify --key k.pub img\nWrite-Output done'''\n  sh 'docker push registry.example.com/app:1.0'\n}\n"),
    ('V2X03_python_shell_true_string', 'unknown', 'quiet', 'node {\n  sh \'\'\'#!/usr/bin/env python3\nimport subprocess\nsubprocess.run("cosign verify --key cosign.pub registry.example.com/app:1.0", shell=True)\n\'\'\'\n  sh \'docker push registry.example.com/app:1.0\'\n}\n'),
    ('V2E02_same_when_check_stage_and_publish_stage', 'quiet', 'finding-high', "pipeline {\n  agent any\n  stages {\n    stage('V') { when { branch 'main' }\n      steps { sh 'obaaf verify release --policy p.json --artifacts dist/a.tgz' } }\n    stage('P') { when { branch 'main' }\n      steps { sh 'make dist' }\n      post { always { sh 'twine upload dist/*' } } }\n  }\n}\n"),
    ('V2E05_earlier_parallel_checks_then_publish_stage', 'quiet', 'finding-high', "pipeline {\n  agent any\n  stages {\n    stage('Checks') { parallel {\n      stage('V1') { steps { sh 'obaaf verify release --policy p.json --artifacts dist/a.tgz' } }\n      stage('V2') { steps { sh 'sha256sum -c SUMS' } } } }\n    stage('P') { steps { sh 'make dist' }\n      post { always { sh 'twine upload dist/*' } } }\n  }\n}\n"),
    ('V2E06_earlier_unread_check_stage_post_always', 'finding-high', 'finding-high', "pipeline {\n  agent any\n  stages {\n    stage('V') { steps { sh 'cosign verify --key cosign.pub registry.example.com/app:1.0 && echo verified' } }\n    stage('P') { steps { sh 'make dist' }\n      post { always { sh 'docker push registry.example.com/app:1.0' } } }\n  }\n}\n"),
    ('V2U03_when_check_two_publishes', 'finding-high', 'finding-high', "pipeline {\n  agent any\n  stages {\n    stage('V') { when { branch 'main' }\n      steps { sh 'obaaf verify release --policy p.json --artifacts dist/a.tgz' } }\n    stage('P1') { when { branch 'main' }\n      steps { sh 'twine upload dist/*' } }\n  }\n  post { success { sh 'docker push registry.example.com/app:1.0' } }\n}\n"),
    ('V2U04_unread_check_two_publishes', 'finding-high', 'finding-high', "pipeline {\n  agent any\n  stages {\n    stage('V') { when { branch 'main' }\n      steps { sh 'cosign verify --key cosign.pub registry.example.com/app:1.0 && echo ok' } }\n    stage('P1') { when { branch 'main' }\n      steps { sh 'docker push registry.example.com/app:1.0' } }\n    stage('P2') { steps { sh 'twine upload dist/*' } }\n  }\n}\n"),
